package com.ecommerce.order.service; import jakarta.persistence.*; import java.math.*; import java.time.*; import java.util.*; @Entity @Table(name="orders",indexes=@Index(name="idx_order_customer",columnList="customer_id")) public class Order { @Id @GeneratedValue(strategy=GenerationType.UUID) UUID id; @Column(nullable=false) UUID customerId; @Column(nullable=false,precision=14,scale=2) BigDecimal total; @Enumerated(EnumType.STRING) @Column(nullable=false) Status status=Status.PENDING_PAYMENT; Instant createdAt=Instant.now(); public enum Status{PENDING_PAYMENT,PAID,PROCESSING,SHIPPED,DELIVERED,CANCELLED} public UUID getId(){return id;} public UUID getCustomerId(){return customerId;} public void setCustomerId(UUID v){customerId=v;} public BigDecimal getTotal(){return total;} public void setTotal(BigDecimal v){total=v;} public Status getStatus(){return status;} public void setStatus(Status v){status=v;} public Instant getCreatedAt(){return createdAt;} }